}

#website .contact-us #contact p {
    max-width: 650px;
    margin: auto;
    font-size: 17px;
    letter-spacing: .2px;
    padding: 20px 0 40px 0
}

#website .contact-us #contact .map {
    background: url(/assets/1011299-f57f54d30/contact_us/map_goleta-f87f7a2062ce73ee414181551d5276928ec8a221eaaddf23367b49cbffbff310.png) no-repeat;
    background-position: center;
    background-size: cover;
    height: 380px;
    margin-top: 80px;
    margin-bottom: 80px;
    width: 100%;
    max-width: 100%
}

#website .contact-us #contact .address {
    font-size: 18px;
    color: #526c1f
}

#website .contact-us #contact .social-icons-container {
    display: flex;
    justify-content: center;
    align-items: center;
    padding-top: 10px
}

#website .contact-us #contact .social-icons-container a {
    margin-right: 24px;
    border: 3px solid #618025;
    border-radius: 50%;
    width: 56px;
    height: 56px;
    display: flex;
    justify-content: center;
    align-items: center
}

#website .contact-us #contact .social-icons-container a i {
    font-size: 25px;
    color: #618025
}

@media(max-width: 767px) {
    #website .contact-us h3 {
        font-size: 22px;
        line-height: 28px
    }

    #website .contact-us #outer-container .form-column {
        height: 900px
    }

    #website .contact-us #outer-container .form-column p {
        font-size: 14px
    }

    #website .contact-us #outer-container .form-column .call {
        padding: 10% 5%
    }

    #website .contact-us #outer-container .form-column .close-form {
        margin-top: 10px;
        margin-right: 10px
    }

    #website .contact-us #outer-container .form-column .form {
        padding: 0 5%
    }

    #website .contact-us #outer-container .form-column .form .form-success h3 {
        font-size: 22px;
        line-height: 28px
    }

    #website .contact-us .container.social {
        display: flex;
        flex-direction: column;
        align-items: center
    }

    #website .contact-us #contact .social-icons-container a {
        margin-right: 18px
    }
}